83	// imageScanJob pairs a display name (used as cache key) with the actual Trivy
84	// scan target. For untagged images the target is the short image ID so Trivy
85	// resolves the image locally instead of pulling "repo:latest" from a registry.
86	type imageScanJob struct {
87		Name   string // cache key and display name
88		Target string // Trivy scan target (may differ from Name for untagged images)
89	}
90	
91	// scanOneImageCmd scans a single image, using a semaphore to limit concurrency.
92	// It emits ImageScanStartingMsg before scanning and ImageScanFinishedMsg after.
93	func scanOneImageCmd(job imageScanJob, opts scan.ScanOptions, sem chan struct{}) tea.Cmd {
94		return tea.Sequence(
95			func() tea.Msg {
96				return ImageScanStartingMsg{ImageName: job.Name}
97			},
98			func() tea.Msg {
99				sem <- struct{}{}
100				defer func() { <-sem }()
101	
102				scanner := scan.NewScanner(opts)
103				result, err := scanner.Scan(context.Background(), job.Target, scan.TargetImage)
104				if err != nil {
105					log.Printf("ERROR: Scan failed for %s: %v", job.Name, err)
106					return ImageScanFinishedMsg{ImageName: job.Name, Err: err}
107				}
108	
109				// Scan() never returns a non-nil error; scanner errors land in result.Errors.
110				// If every scanner failed (errors present, no findings), surface it as an error.
111				if len(result.Errors) > 0 && result.TotalFindings() == 0 {
112					combined := strings.Join(result.Errors, "; ")
113					log.Printf("ERROR: Scan errors for %s: %s", job.Name, combined)
114					return ImageScanFinishedMsg{ImageName: job.Name, Err: fmt.Errorf("%s", combined)}
115				}
116	
117				entry := cache.ImageScanEntry{
118					Critical:  result.Counts.Critical,
119					High:      result.Counts.High,
120					Medium:    result.Counts.Medium,
121					Low:       result.Counts.Low,
122					ScannedAt: result.EndTime,
123				}
124				scanCache, cErr := cache.NewImageScanCache()
125				if cErr != nil {
126					log.Printf("ERROR: Failed to open scan cache: %v", cErr)
127				} else if sErr := scanCache.Set(job.Name, entry); sErr != nil {
128					log.Printf("ERROR: Failed to cache scan for %s: %v", job.Name, sErr)
129				}
130				// Rule 126: persist full result so Enter can load it without re-scanning
131				if sErr := cache.SaveImageScanResult(job.Name, result); sErr != nil {
132					log.Printf("ERROR: Failed to save full scan result for %s: %v", job.Name, sErr)
133				}
134				return ImageScanFinishedMsg{ImageName: job.Name, Entry: entry}
135			},
136		)
137	}
