139	// batchScanCmd scans all provided images in parallel using a worker pool
140	// of runtime.NumCPU()/2 workers (minimum 1).
141	func batchScanCmd(jobs []imageScanJob, opts scan.ScanOptions) tea.Cmd {
142		numWorkers := max(runtime.NumCPU()/2, 1)
143		sem := make(chan struct{}, numWorkers)
144	
145		cmds := make([]tea.Cmd, len(jobs))
146		for i, job := range jobs {
147			cmds[i] = scanOneImageCmd(job, opts, sem)
148		}
149		return tea.Batch(cmds...)
150	}
