348	// doRegistryGETBytes performs a GET on rawURL, handling bearer token auth on 401.
349	func doRegistryGETBytes(rawURL, username, password string) ([]byte, error) {
350		req, err := http.NewRequest("GET", rawURL, nil)
351		if err != nil {
352			return nil, fmt.Errorf("build request: %w", err)
353		}
354		if username != "" && password != "" {
355			req.SetBasicAuth(username, password)
356		}
357		resp, err := ociHTTPClient.Do(req)
358		if err != nil {
359			return nil, fmt.Errorf("GET %s: %w", rawURL, err)
360		}
361		defer func() { _ = resp.Body.Close() }()
362	
363		if resp.StatusCode == http.StatusUnauthorized {
364			wwwAuth := resp.Header.Get("Www-Authenticate")
365			if !strings.HasPrefix(wwwAuth, "Bearer ") {
366				return nil, fmt.Errorf("unexpected auth challenge: %s", wwwAuth)
367			}
368			token, tErr := exchangeBearerToken(wwwAuth[7:], username, password)
369			if tErr != nil {
370				return nil, tErr
371			}
372			req2, err := http.NewRequest("GET", rawURL, nil)
373			if err != nil {
374				return nil, fmt.Errorf("build retry request: %w", err)
375			}
376			req2.Header.Set("Authorization", "Bearer "+token)
377			resp2, err := ociHTTPClient.Do(req2)
378			if err != nil {
379				return nil, fmt.Errorf("GET (retry) %s: %w", rawURL, err)
380			}
381			defer func() { _ = resp2.Body.Close() }()
382			if resp2.StatusCode != http.StatusOK {
383				return nil, fmt.Errorf("registry returned %d", resp2.StatusCode)
384			}
385			return io.ReadAll(resp2.Body)
386		}
387		if resp.StatusCode != http.StatusOK {
388			return nil, fmt.Errorf("registry returned %d", resp.StatusCode)
389		}
390		return io.ReadAll(resp.Body)
391	}
392	
393	// exchangeBearerToken fetches a bearer token from the registry's token endpoint.
394	func exchangeBearerToken(challenge, username, password string) (string, error) {
395		params := parseBearerChallenge(challenge)
396		realm, ok := params["realm"]
397		if !ok {
398			return "", fmt.Errorf("bearer challenge missing realm")
399		}
400		u, err := url.Parse(realm)
401		if err != nil {
402			return "", fmt.Errorf("parse realm %q: %w", realm, err)
403		}
404		q := u.Query()
405		if s, ok := params["service"]; ok {
406			q.Set("service", s)
407		}
408		if s, ok := params["scope"]; ok {
409			q.Set("scope", s)
410		}
411		u.RawQuery = q.Encode()
412	
413		req, err := http.NewRequest("GET", u.String(), nil)
414		if err != nil {
415			return "", fmt.Errorf("build token request: %w", err)
416		}
417		if username != "" && password != "" {
418			req.SetBasicAuth(username, password)
419		}
420		resp, err := ociHTTPClient.Do(req)
421		if err != nil {
422			return "", fmt.Errorf("fetch token: %w", err)
423		}
424		defer func() { _ = resp.Body.Close() }()
425		if resp.StatusCode != http.StatusOK {
426			return "", fmt.Errorf("token endpoint returned %d", resp.StatusCode)
427		}
428		body, err := io.ReadAll(resp.Body)
429		if err != nil {
430			return "", fmt.Errorf("read token response: %w", err)
431		}
432		var result struct {
433			Token       string `json:"token"`
434			AccessToken string `json:"access_token"`
435		}
436		if err := json.Unmarshal(body, &result); err != nil {
437			return "", fmt.Errorf("decode token response: %w", err)
438		}
439		if result.Token != "" {
440			return result.Token, nil
441		}
442		if result.AccessToken != "" {
443			return result.AccessToken, nil
444		}
445		return "", fmt.Errorf("token response contained no token field")
446	}
447	
448	// parseBearerChallenge parses the value portion of a Www-Authenticate: Bearer header.
449	// Example: `realm="https://auth.docker.io/token",service="registry.docker.io"`
450	func parseBearerChallenge(s string) map[string]string {
451		params := make(map[string]string)
452		for _, part := range strings.Split(s, ",") {
453			part = strings.TrimSpace(part)
454			idx := strings.IndexByte(part, '=')
455			if idx < 0 {
456				continue
457			}
458			key := strings.TrimSpace(part[:idx])
459			val := strings.Trim(strings.TrimSpace(part[idx+1:]), `"`)
460			params[key] = val
461		}
462		return params
463	}
